#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

umask 077
BASE=/opt/bizbase-prod
STAGE=$BASE/routes-release.qdosgjp8
TOOLS=$STAGE/window-tools
W=$STAGE/window-state
D=$BASE/slots/maintenance
SITE=bizbase.geokeji.com
SITES=/var/lib/bizbase-prod/sites
UPSTREAM=/www/server/panel/vhost/nginx/bizbase-upstream.inc
IMAGE=sha256:69201531ea25f4624a53b0c37c43f2c6f5526151a63f2ca0f4b43a700290d30d
TIMER=bizbase-yishan-id.timer
SERVICE=bizbase-yishan-id.service
HERE=$(cd "$(dirname "$0")" && pwd -P)
FILES=(routes_window.sh routes_checks.py deploy.sh compose.yaml sync_yishan_id.py check_login.py pg16_schema.py rehearse_routes.py rehearsal_checks.py preserve_geo.py rename_yishan_id.py rename_file_share.py)
fail() { echo "停止：$*" >&2; exit 1; }
usage() {
cat <<'HELP'
本机设置 ROUTES_SSH 为 root 的 SSH 配置别名，ROUTES_VAULT 为本机私有归档目录。
ROUTES_VAULT 中已有 recipient.pem 与 recovery.key；私钥只在本机使用。
可用 wizard 逐项确认。中断后按宿主状态选用子命令续接。
在仓库用 rtk proxy bash deploy/prod/routes_window.sh 逐条执行以下参数：
  stage                          上传工具，核对本机和宿主工具及收件证书摘要
  host prepare /var/lib/bizbase-rehearsals/routes-已完成的apply目录
  host freeze                    停 timer、等待 service、检查本站队列，再冻结
  host backup                    停写期间的数据库、文件、部署配置及旧指纹
  host verify                    PG16 断网还原、逐表核对及 GEO 单独导出
  host archive                   生成加密协调备份
  fetch                          下载到本机，校验密文、解密并核对全部成员
  confirm-copy                   用本机取得的回执登记 D checkpoint
  host baseline                  冻结后的旧镜像权限/文件指纹及 GEO 卸载预览
  host geo                       人工复核 dry-run 后单独应用已演练的 GEO 归档迁移
  host rename                    卸载空 GEO，紧接两个改名
  host manifest                  D 原子换清单
  host install                   依演练顺序补装应用并复核四看板禁用
  host migrate                   D migrate 和 clear-cache
  host preview                   仅启动候选网页，做完整验收，留存新指纹
  compare                        下载指纹，在本机逐类比对，生成切流回执
  publish                        校验本机回执后执行 D publish，恢复身份同步
  host public-check              公网浏览器、OIDC、深链与 timer 复核
  host accept                    人工完成实际扫码/退出后归档 D 窗口
  host status                    查看 D 阶段和检查点
  host isolate                   运维决定隔离两个槽，保留 D 故障现场
每次失败均停止。排障和恢复依 OPERATIONS.md 的 D 流程。先核实外部写入者已停止、身份平台已登记新回调。
HELP
}
# The optional workstation wizard uses exactly the same individual commands as the CLI.
run_wizard() {
    TOTAL_STAGES=7
    local replay_dir
    banner "BizBase 生产 D 类发布"
    stage "上传工具并准备 D 窗口"
    step "在宿主找到已通过 GEO 归档迁移及最终校验的 replay 结果目录。"
    ask replay_dir "成功 apply 的绝对目录（含 apply-ok 和 review.json）"
    confirm "核对 SSH 目标、备份空间和新旧身份回调后，上传并 prepare？" || return 1
    bash "$0" stage; bash "$0" host prepare "$replay_dir"
    stage "停写并取协调检查点"
    confirm "已停止站外写入者，现在冻结生产并备份？" || return 1
    bash "$0" host freeze; bash "$0" host backup; bash "$0" host verify
    stage "取得异机加密副本"
    bash "$0" host archive; bash "$0" fetch
    confirm "本机已妥善留存密文和恢复密钥，登记检查点？" || return 1
    bash "$0" confirm-copy; bash "$0" host baseline
    stage "GEO 私有归档与两个应用改名"
    step "在宿主私有目录查看 window-state/geo-dry-run.log，核对卸载对象。"
    confirm "dry-run 范围符合演练，执行旧镜像 GEO 归档和改名？" || return 1
    bash "$0" host geo; bash "$0" host rename
    stage "候选安装、迁移与预览"
    confirm "换候选清单并执行 install、migrate 和回环验收？" || return 1
    bash "$0" host manifest; bash "$0" host install; bash "$0" host migrate; bash "$0" host preview
    stage "离线比对和实际切流"
    bash "$0" compare
    confirm "离线全量指纹比对已通过，现在将生产流量和队列交给候选槽？" || return 1
    bash "$0" publish; bash "$0" host public-check
    stage "公网验收与关闭窗口"
    step "用真实账号验证扫码登录、后端退出、受限账号访问四看板的结果，以及历史分享授权与深链。"
    confirm "实际业务验收完成，归档本次 D 窗口？" || return 1
    bash "$0" host accept
    finish
}
cmd=${1:---help}; shift || true
case $cmd in wizard) run_wizard; exit ;; help|-h|--help) usage; exit ;; esac
# Workstation commands use only one named SSH destination. No remote command is inferred from input.
remote() { ssh -T -o BatchMode=yes "${ROUTES_SSH:?请设置 root SSH 别名}" "$@"; }
vault() { V=${ROUTES_VAULT:?请设置私有归档目录}; [[ -d $V && ! -L $V && -r $V/recipient.pem ]] || fail '归档目录或证书缺失'; }
call_host() {
    local a quoted=()
    for a in "$@"; do [[ $a =~ ^[A-Za-z0-9_./:-]+$ ]] || fail '宿主参数含意外字符'; quoted+=("$a"); done
    remote "bash $TOOLS/routes_window.sh on-host ${quoted[*]}"
}
case $cmd in
stage)
    vault
    # Install in a fresh directory, publish atomically. Do not replace tools in an existing window.
    COPYFILE_DISABLE=1 tar -cf - -C "$HERE" "${FILES[@]}" | remote "set -eu; umask 077; cd $STAGE; d=\$(mktemp -d window-upload.XXXXXX); tar -xf - -C \"\$d\"; if test -d window-tools; then diff -qr window-tools \"\$d\"; else mv -T \"\$d\" window-tools; fi"
    (cd "$HERE"; shasum -a 256 "${FILES[@]}") | remote "cd $TOOLS && sha256sum -c -"
    shasum -a 256 <"$V/recipient.pem" | remote "cd $STAGE && read -r hash rest && echo \"\$hash  recipient.pem\" | sha256sum -c -" ;;
host) call_host "$@" ;;
fetch)
    vault; id=$(call_host backup-id); [[ $id =~ ^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{8}$ ]] || fail '非法备份编号'
    dir=$V/$id; mkdir -p "$dir"; tmp=$(mktemp -d "$dir/.verify.XXXXXX"); trap 'rm -rf "$tmp"' EXIT
    remote "cat $W/$id.cms" >"$tmp/copy.cms"
    hash=$(shasum -a 256 "$tmp/copy.cms"); [[ ${hash%% *} == "$(call_host archive-sha)" ]] || fail '密文摘要不符'
    openssl cms -decrypt -binary -inform DER -in "$tmp/copy.cms" -recip "$V/recipient.pem" -inkey "$V/recovery.key" |
        python3 -I "$HERE/routes_checks.py" archive "$id" "$tmp/baseline.sha256" >"$tmp/copy.receipt"
    mv "$tmp/copy.cms" "$dir/$id.cms"; mv "$tmp/baseline.sha256" "$dir/baseline.sha256"; mv "$tmp/copy.receipt" "$dir/copy.receipt"
    echo "异机完整核验通过：$dir/$id.cms" ;;
confirm-copy|publish|compare)
    vault; id=$(call_host backup-id); [[ $id =~ ^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{8}$ ]] || fail '非法备份编号'; dir=$V/$id
    case $cmd in
    confirm-copy) call_host checkpoint "$(cat "$dir/copy.receipt")" ;;
    compare)
        [[ -s $dir/$id.cms ]] || fail '未找到异机协调备份'; tmp=$(mktemp -d "$dir/.checks.XXXXXX")
        for f in id old.inventory new.inventory old.business new.business preview.ok; do remote "cat $W/$f" >"$tmp/$f"; done
        baseline=$(shasum -a 256 "$tmp/old.inventory"); [[ ${baseline%% *} == "$(cat "$dir/baseline.sha256")" ]] || fail '旧指纹与异机冻结包不符'
        [[ $(cat "$tmp/id") == "$id" ]] || fail '检查点变化'; python3 -I "$HERE/routes_checks.py" compare "$tmp" >"$tmp/compare.receipt"
        cp "$tmp/compare.receipt" "$dir/compare.receipt"; echo "离线比对通过：$tmp" ;;
    publish) call_host publish "$(cat "$dir/compare.receipt")" ;;
    esac ;;
on-host) ;;
*) fail '未知命令，可用 --help 查看' ;;
esac
[[ $cmd == on-host ]] || exit 0
[[ $EUID == 0 && $HERE == "$TOOLS" && -d $STAGE/before ]] || fail '需在指定宿主暂存目录以 root 运行'
# Pin deployment defaults and Docker socket; inherited overrides could select another site/engine.
while read -r name; do unset "$name"; done < <(compgen -A variable BIZBASE_ || true)
unset DOCKER_CONTEXT COMPOSE_FILE COMPOSE_PROJECT_NAME
export DOCKER_HOST=unix:///var/run/docker.sock
mkdir -p "$W"; cd "$W"; exec 9>lock; flock -n 9 || fail '另一窗口操作正在执行'
action=${1:-status}; shift || true
maint() { "$BASE/deploy.sh" maintenance "$@"; }
phase() { local actual; actual=$(cat "$D/phase"); [[ " $* " == *" $actual "* ]] || fail "D 当前阶段为 $actual"; }
project() { case $1 in legacy) echo bizbase-prod ;; blue|green) echo "bizbase-prod-$1" ;; *) fail '未知槽位' ;; esac; }
container() { local c; c=$(docker ps -q --filter "label=com.docker.compose.project=$(project "$1")" --filter "label=com.docker.compose.service=$2"); [[ $c =~ ^[0-9a-f]+$ ]] || fail "槽位 $1 服务 $2 数量异常"; echo "$c"; }
quiet_slots() { local s c; for s in legacy blue green; do c=$(docker ps -q --filter "label=com.docker.compose.project=$(project "$s")"); [[ -z $c ]] || fail "$s 槽仍在运行"; done; }
run_check() { python3 -I "$TOOLS/routes_checks.py" "$@"; }
replay_ok() {
    run_check replay "$2" "$TOOLS" "$1" "$IMAGE"
    [[ $(docker image inspect -f '{{.Id}} {{.Os}}/{{.Architecture}}' "$IMAGE") == "$IMAGE linux/amd64" ]] || fail '候选镜像身份不符'
}
sums() { sha256sum "$TOOLS"/*.{sh,py,yaml} "$STAGE"/{inventory.py,browser_cdp.py,recipient.pem}; }
pin_check() {
    cmp "$BASE/deploy.sh" "$TOOLS/deploy.sh"
    cmp "$BASE/compose.yaml" "$TOOLS/compose.yaml"
    cmp "$BASE/.env" "$STAGE/before/.env"
    sha256sum --quiet -c pinned.sha256 || fail '脚本或输入摘要已变化'
}
atomic_install() { local tmp; tmp=$(mktemp "$BASE/.routes.XXXXXX"); install -m "$3" "$1" "$tmp"; mv -fT "$tmp" "$2"; }
# A stopped slot is never started for probes. Only the pinned candidate interpreter
# reads the mounted site configuration and RQ metadata in the frozen phase.
readonly_probe() { docker run -i --rm --pull=never --log-driver=none --network "$(project "$(cat "$D/old")")_default" -v "$SITES:/home/frappe/frappe-bench/sites:ro" --entrypoint env/bin/python "$IMAGE" - "$@"; }
queue_check() { readonly_probe queue <"$TOOLS/routes_checks.py"; }
no_timer() {
    local unit state
    for unit in "$TIMER" "$SERVICE"; do
        state=$(systemctl show -p ActiveState --value "$unit"); [[ $state == inactive ]] || fail "$unit 为 $state，需运维检查"
    done
}
stop_timer() {
    systemctl disable --now "$TIMER"; local n
    for n in {1..35}; do [[ $(systemctl show -p ActiveState --value "$SERVICE") == inactive ]] && break; sleep 1; done
    no_timer
}
browser() {
    local front; front=$(container "$1" frontend); shift
    docker run --rm -i --pull=never --log-driver=none --network "container:$front" -v "$STAGE/browser_cdp.py:/check/browser.py:ro" --entrypoint env/bin/python "$IMAGE" /check/browser.py "$@" </etc/bizbase/initial-admin-password
}
business() {
    local side=$1; shift
    tar -cf - -C "$TOOLS" preserve_geo.py rehearsal_checks.py | "$@" env/bin/python -c "$(cat "$TOOLS/routes_checks.py")" business "$side" >"$side.business.tmp"
    mv "$side.business.tmp" "$side.business"
}
geo_sha() { sha256sum "/var/backups/bizbase-pg16/$(cat id)/geo-preservation-v1.json" | cut -d' ' -f1; }
geo_check() { maint "$1" env/bin/python - "$2" --site "$SITE" --sha256 "$(geo_sha)" <"$TOOLS/preserve_geo.py"; }
case $action in
status) "$BASE/deploy.sh" status; if [[ -f id ]]; then cat id; fi; exit ;;
isolate) cmp "$BASE/deploy.sh" "$TOOLS/deploy.sh"; systemctl disable --now "$TIMER" || echo "请手动检查 timer" >&2; maint isolate; no_timer; exit ;;
backup-id) cat id; exit ;;
archive-sha) sha256sum "$(cat id).cms" | cut -d' ' -f1; exit ;;
prepare)
    [[ $# == 1 ]] || fail '指定成功的 apply 目录'; [[ ! -d $D ]] || phase prepared
    before=$STAGE/before
    for f in compose.yaml .env sync_yishan_id.py check_login.py; do cmp "$BASE/$f" "$before/$f"; done
    cmp "$UPSTREAM" "$before/bizbase-upstream.inc"; cmp "$TOOLS/compose.yaml" "$BASE/compose.yaml"
    cmp -s "$BASE/deploy.sh" "$before/deploy.sh" || cmp "$BASE/deploy.sh" "$TOOLS/deploy.sh"
    old=$(docker inspect -f '{{.Image}}' "$(container legacy backend)"); replay_ok "$old" "$1"
    if [[ -f replay && -d $D ]]; then [[ $(cat replay) == "$1" ]] || fail '已有其他 replay'; fi
    printf '%s\n' "$1" >replay
    for svc in backend websocket frontend scheduler worker; do [[ $(docker inspect -f '{{.Image}}' "$(container legacy "$svc")") == "$old" ]] || fail '旧槽镜像混用'; done
    if [[ ! -f pre-window.tar ]]; then
        parts=("${BASE#/}/.env" "${STAGE#/}/before" "${UPSTREAM#/}" etc/bizbase); [[ ! -d $BASE/slots ]] || parts+=("${BASE#/}/slots")
        tar --numeric-owner -cpf pre-window.tmp -C / "${parts[@]}"; mv pre-window.tmp pre-window.tar
    fi
    if [[ ! -f timer.state ]]; then
        enabled=$(systemctl show -p UnitFileState --value "$TIMER"); active=$(systemctl show -p ActiveState --value "$TIMER")
        [[ $enabled =~ ^(enabled|disabled)$ && $active =~ ^(active|inactive)$ ]] || fail 'timer 初始状态异常'; printf '%s %s\n' "$enabled" "$active" >timer.state
    fi
    (cd "$STAGE"; sha256sum --quiet -c - <<'PROBES'
b0d1e745d09cac7391683cd752769530384c7f2077b92fd3d4c75d169dc2ff32  inventory.py
573983af859cfa4c56e4a8f2e5774e52cf84e5930f45c63482236828c8c11754  browser_cdp.py
PROBES
    )
    openssl x509 -in "$STAGE/recipient.pem" -noout -checkend 0
    test -s /etc/bizbase/initial-admin-password
    docker image inspect postgres:16-alpine >/dev/null
    if [[ -f pinned.sha256 ]]; then sha256sum --quiet -c pinned.sha256; else sums >pinned.tmp; mv pinned.tmp pinned.sha256; fi
    browser legacy http://127.0.0.1:8080 baseline
    atomic_install "$TOOLS/deploy.sh" "$BASE/deploy.sh" 0755
    if [[ ! -d $D ]]; then [[ ! -f window.inode ]] || fail '先前窗口已结束'; maint begin "$IMAGE"; fi
    stat -c %i "$D" >window.inode
    [[ $(cat "$D/old") == legacy && $(cat "$D/old.image") == "$old" && $(cat "$D/new.image") == "$IMAGE" ]] || fail 'D 窗口与演练不符'; exit ;;
esac
pin_check
[[ $(stat -c %i "$D") == "$(cat window.inode)" && $(cat "$D/old") == legacy && $(cat "$D/new.image") == "$IMAGE" ]] || fail '当前 D 窗口与 prepare 不符'
case $action in
freeze)
    phase prepared freezing; replay_ok "$(cat "$D/old.image")" "$(cat replay)"; cmp "$BASE/compose.yaml" "$TOOLS/compose.yaml"; cmp "$BASE/.env" "$STAGE/before/.env"
    if [[ $(cat "$D/phase") == prepared ]]; then
        [[ $(docker inspect -f '{{.Image}}' "$(container legacy backend)") == "$(cat "$D/old.image")" ]] || fail '旧镜像已变化'; queue_check
    fi
    stop_timer; maint freeze; quiet_slots; queue_check ;;
backup)
    phase frozen; no_timer; quiet_slots; queue_check; [[ ! -f backup.ok ]] || fail '已备份'
    if [[ ! -f id ]]; then
        python3 -I "$TOOLS/pg16_schema.py" backup >backup.log
        id=$(sed -nE 's@^.* /var/backups/bizbase-pg16/([0-9]{8}T[0-9]{6}Z-[0-9a-f]{8})，SHA-256 [0-9a-f]{64}$@\1@p' backup.log)
        [[ $id =~ ^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{8}$ && -s /var/backups/bizbase-pg16/$id/manifest.json ]] || fail '请核对 backup.log'; echo "$id" >id
    fi
    readonly_probe old <"$STAGE/inventory.py" >old.inventory.tmp; mv old.inventory.tmp old.inventory
    tar --numeric-owner -cpf sites.tmp -C "${SITES%/*}" sites; tar --compare -f sites.tmp -C "${SITES%/*}"; mv sites.tmp sites.tar
    systemctl cat "$TIMER" "$SERVICE" >systemd.units
    tar --numeric-owner -cpf host.tmp -C / "${BASE#/}/slots" "${BASE#/}/deploy.sh" "${BASE#/}/compose.yaml" "${BASE#/}/.env" "${UPSTREAM#/}" etc/bizbase "${TOOLS#/}" -C "$W" pre-window.tar timer.state pinned.sha256 replay systemd.units
    mv host.tmp host.tar; quiet_slots; queue_check; touch backup.ok ;;
verify)
    phase frozen; quiet_slots; no_timer; [[ -f backup.ok ]] || fail '先完成 backup'; id=$(cat id)
    python3 -I "$TOOLS/pg16_schema.py" verify "$id"; python3 -I "$TOOLS/preserve_geo.py" backup "$id"
    [[ $(geo_sha) == "$(python3 -I -c 'import json,sys; print(json.load(open(sys.argv[1]))["baseline"]["geo_archive"])' "$(cat replay)/review.json")" ]] || fail 'GEO 内容与成功演练不符'
    tar --compare -f sites.tar -C "${SITES%/*}"; touch verified ;;
archive)
    phase frozen; quiet_slots; [[ -f verified ]] || fail '先 verify'; id=$(cat id); db=/var/backups/bizbase-pg16/$id
    if [[ ! -f $id.cms ]]; then
        for f in bizbase_app.dump manifest.json geo-preservation-v1.json; do cp "$db/$f" "$f"; done
        openssl rand -hex 32 >receipt
        members=(id bizbase_app.dump manifest.json geo-preservation-v1.json sites.tar host.tar old.inventory receipt)
        sha256sum "${members[@]}" >SHA256SUMS
        tar -cf - "${members[@]}" SHA256SUMS | openssl cms -encrypt -binary -stream -aes-256-cbc -outform DER -out "$id.cms.tmp" "$STAGE/recipient.pem"
        mv "$id.cms.tmp" "$id.cms"
    fi
    sha256sum "$id.cms" ;;
checkpoint)
    phase frozen; quiet_slots; queue_check; no_timer; [[ -s $(cat id).cms && -f verified && ${1:-} == "$(cat receipt)" ]] || fail '异机备份未确认'; maint checkpoint "$(cat id)" ;;
baseline)
    phase backed-up; [[ ! -e geo.started ]] || fail 'GEO 已开始，保留原基线'; no_timer
    rm -f baseline.ok; business old maint old
    maint old bench --site "$SITE" uninstall-app geo_operations --dry-run >geo-dry-run.log
    grep -Fq 'Uninstalled App geo_operations' geo-dry-run.log; grep -Fq 'removing Module Def' geo-dry-run.log
    echo "请审阅 $W/geo-dry-run.log 后再调用 geo"; touch baseline.ok ;;
geo)
    phase backed-up; [[ -f baseline.ok ]] || fail '先核对旧站基线'; touch geo.started; geo_check old apply; touch geo.ok ;;
rename)
    phase backed-up; [[ -f geo.ok ]] || fail '先完成 GEO 手动阶段'
    if [[ ! -f geo.removed ]]; then maint old bench --site "$SITE" uninstall-app geo_operations --yes --no-backup; touch geo.removed; fi
    if [[ ! -f id.renamed ]]; then maint old env/bin/python - --site "$SITE" <"$TOOLS/rename_yishan_id.py"; touch id.renamed; fi
    maint old env/bin/python - --site "$SITE" <"$TOOLS/rename_file_share.py"; touch renamed ;;
manifest) phase backed-up; [[ -f renamed ]] || fail '旧镜像步骤未完成'; maint manifest ;;
install)
    phase candidate
    for app in crm insights bizbase_mgmt sales_board ops_board customer_board; do
        if [[ ! -f installed.$app ]]; then maint new bench --site "$SITE" install-app "$app"; touch "installed.$app"; fi
    done
    geo_check new verify; touch installed ;;
migrate) phase candidate; [[ -f installed ]] || fail '应用或 GEO 复核未完成'; maint migrate ;;
preview)
    phase migrated preview; rm -f preview.ok; no_timer; maint preview; new=$(cat "$D/new"); backend=$(container "$new" backend)
    docker exec -i "$backend" env/bin/python - new <"$STAGE/inventory.py" >new.inventory.tmp; mv new.inventory.tmp new.inventory
    business new docker exec -i "$backend"
    browser "$new" http://127.0.0.1:8080
    openssl rand -hex 32 >preview.ok ;;
publish)
    phase preview publishing published; [[ -s preview.ok ]] || fail '预览未通过'; checked=$(run_check compare "$W"); [[ ${1:-} == "$checked" ]] || fail '离线比对回执不匹配'
    atomic_install "$TOOLS/sync_yishan_id.py" "$BASE/sync_yishan_id.py" 0755; atomic_install "$TOOLS/check_login.py" "$BASE/check_login.py" 0755
    if [[ $(cat "$D/phase") != published ]]; then maint publish; fi
    systemctl start "$SERVICE"; read -r enabled active <timer.state
    if [[ $enabled == enabled ]]; then systemctl enable "$TIMER"; fi
    if [[ $active == active ]]; then systemctl start "$TIMER"; fi ;;
public-check)
    phase published; rm -f public.ok; python3 -I "$TOOLS/check_login.py"; browser "$(cat "$D/new")" "https://$SITE"
    python3 -I -c 'import json,time; v=json.load(open("/etc/bizbase/yishan-runtime/settings.json")); assert v["verified_until"] > time.time()'
    read -r enabled active <timer.state; [[ $(systemctl show -p UnitFileState --value "$TIMER") == "$enabled" && $(systemctl show -p ActiveState --value "$TIMER") == "$active" ]] || fail 'timer 未恢复'; touch public.ok ;;
accept) phase published; [[ -f public.ok ]] || fail '公网验收未完成'; maint accept ;;
*) fail '未知宿主阶段' ;;
esac
